#!/bin/bash
# =============================================================================
# swatches-aco.sh — QA test: a Photoshop .aco shown in the Swatches panel the way
# it was made. The fixture (QA/fixtures/swatches-pad.aco, generated by
# make-swatch-fixtures.py) is 6 wide: rows of 4 ramp colors padded with black.
# An .aco has no column count, so it is guessed (6), and the black filler turns
# into empty cells - all but the first black: 22 entries, 5 empty.
# QA-OPTIONS: WORKSPACE=default DOCK_DUMP=QA/.dock-dump.txt SWATCHES_VISIBLE=1 SWATCHES_SET=QA/fixtures/swatches-pad.aco SWATCHES_COLS=0 SWATCHES_BLACK_SPACERS=TRUE
# =============================================================================
source "$DRAW_ROOT/QA/dock-lib.sh"

info "=== Swatches: .aco layout ==="
dk_begin
if ! grep -q '^SWAT ' "$DK_DUMP"; then fail "no Swatches panel in the dump (SWAT line missing)"; fi
read -r _ SW_N SW_COLORS SW_COLS _ <<< "$(grep '^SWAT ' "$DK_DUMP")"
spaces=$(awk '$1=="SWATC" && $7==1' "$DK_DUMP" | wc -l)
if [[ "$SW_COLS" == 6 ]]; then pass "guessed 6 columns"; else fail "columns = '$SW_COLS', want 6"; fi
if [[ "$SW_N" == 22 ]]; then pass "22 entries"; else fail "entries = '$SW_N', want 22"; fi
if [[ "$SW_COLORS" == 17 ]]; then pass "17 colors"; else fail "colors = '$SW_COLORS', want 17"; fi
if (( spaces == 5 )); then pass "5 empty cells"; else fail "$spaces empty cells, want 5"; fi
# the ramps line up: entry 7 (row 2, column 1) sits under entry 1
read -r _ _ X1 Y1 _ <<< "$(grep '^SWATC 1 ' "$DK_DUMP")"
read -r _ _ X7 Y7 _ <<< "$(grep '^SWATC 7 ' "$DK_DUMP")"
if [[ -n "$X1" && "$X1" == "$X7" ]] && (( Y7 > Y1 )); then pass "row 2 starts under row 1"; else fail "entry 7 ($X7,$Y7) not under entry 1 ($X1,$Y1)"; fi
screenshot "swatches-aco"
assert_window_exists
info "=== Swatches: .aco layout PASSED ==="
